SELECT id, user_id, app_name, app_desc, app_type, app_screenshot
FROM app
WHERE id = #{appId}

    AND app_type = #{appType}

ORDER BY id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM app
WHERE id = #{appId}

    AND app_type = #{appType}

SELECT a.id, a.user_id, u.nick_name AS user_name, a.app_type, a.app_name, a.app_desc, a.app_screenshot FROM app a LEFT JOIN app_user u ON u.id = a.user_id WHERE a.deploy_status = #{deployStatus}
AND a.app_type = #{query.appType}
ORDER BY a.id DESC LIMIT #{query.offset}, #{query.pageSize}

SELECT COUNT(1)
FROM app a
WHERE a.deploy_status = #{deployStatus}

    AND a.app_type = #{query.appType}
